import itertools

def solve(n):
    num_subsets = 1 << n
    subsets = []
    for i in range(num_subsets):
        s = set()
        for j in range(n):
            if (i >> j) & 1:
                s.add(j)
        subsets.append(s)

    count = 0
    for coloring in itertools.product([0, 1], repeat=num_subsets):
        # coloring[i] is C(subsets[i])
        # f(T) = sum(coloring[i] for i where subsets[i] subset of T)
        f = [0] * num_subsets
        for i in range(num_subsets): # i is the index of T
            for j in range(num_subsets): # j is the index of a subset of T
                if subsets[j].issubset(subsets[i]):
                    f[i] += coloring[j]

        possible = True
        for i in range(num_subsets):
            for j in range(num_subsets):
                t1 = subsets[i]
                t2 = subsets[j]
                union_t = t1.union(t2)
                inter_t = t1.intersection(t2)

                # find indices of union_t and inter_t
                idx_union = -1
                idx_inter = -1
                for k in range(num_subsets):
                    if subsets[k] == union_t:
                        idx_union = k
                    if subsets[k] == inter_t:
                        idx_inter = k

                if f[i] * f[j] != f[idx_union] * f[idx_inter]:
                    possible = False
                    break
            if not possible:
                break
        if possible:
            count += 1
    return count

for n in range(1, 4):
    print(f"n={n}, count={solve(n)}")
